#!/usr/bin/env bash
# Max Player v77 update script
# Run from the repo root: ~/IdeaProjects/maxplayer
set -euo pipefail

if [ ! -f "pubspec.yaml" ]; then
  echo "ERROR: run this from the maxplayer repo root (pubspec.yaml not found here)."
  exit 1
fi

echo "==> Patching lib/state/media_player_state.dart (fix 'new video lags for a second')"
python3 - <<'PYEOF'
import sys
p = "lib/state/media_player_state.dart"
s = open(p, encoding="utf-8").read()
old = """    await player.open(Media(track.path), play: autoplay);
    await player.setRate(playbackRate);
    await _applyMpvVolume();
    await _applyAudioFilters(); // equalizer + leveling survive file changes
    await _attachSidecarSubtitles(track.path);
    await _recordOpen(track);
    await _restoreBookmark(track);"""
new = """    await player.open(Media(track.path), play: autoplay);
    await player.setRate(playbackRate);
    await _applyMpvVolume();
    // v77: these three used to be awaited here too, serially, before this
    // function returned - stacking a disk scan (subtitle attach) and an
    // mpv audio filter-graph rebuild right on top of the file just
    // opening was the real cause of "new video lags for a second". None
    // of them need to finish before the user can start watching, so they
    // now run in the background instead of blocking playback start.
    unawaited(() async {
      await _applyAudioFilters(); // equalizer + leveling survive file changes
      await _attachSidecarSubtitles(track.path);
      await _recordOpen(track);
    }());
    await _restoreBookmark(track);"""
if old not in s:
    sys.exit("[media_player_state.dart] anchor not found, aborting")
s = s.replace(old, new, 1)
open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/widgets/ask_ai_sheet.dart (cache movie AI answers across sheet reopens)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/ask_ai_sheet.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[ask_ai_sheet.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
'''  bool _asking = false;
  String? _answer;
  String? _answerModel;
  String? _error;
  int _askToken = 0;

  @override
  void initState() {
    super.initState();
    _bootCache();
  }''',
'''  bool _asking = false;
  String? _answer;
  String? _answerModel;
  String? _error;
  int _askToken = 0;

  /// v77: in-memory cache of the last question/answer per movie, so
  /// closing this sheet (a dismissible bottom sheet - Flutter tears its
  /// whole State down on close) and reopening it for the same movie
  /// shows what the AI already generated instead of a blank sheet.
  /// Separate from MovieAiClient's 7-day on-disk cache, which only
  /// speeds up re-asking the identical question - this restores what
  /// was actually on screen.
  static final Map<int, ({String question, String answer, String? model})>
      _sessionCache = {};

  @override
  void initState() {
    super.initState();
    _bootCache();
    final cached = _sessionCache[widget.movie.id];
    if (cached != null) {
      _questionCtrl.text = cached.question;
      _answer = cached.answer;
      _answerModel = cached.model;
    }
  }''')

apply(
'''      } else {
        _answer = result.text;
        _answerModel = result.model;
      }''',
'''      } else {
        _answer = result.text;
        _answerModel = result.model;
        _sessionCache[widget.movie.id] = (
          question: q,
          answer: result.text,
          model: result.model,
        );
      }''')

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF

echo "==> Patching lib/widgets/ai_suggest_sheet.dart (restore last AI Suggestor result on reopen)"
python3 - <<'PYEOF'
import sys
p = "lib/widgets/ai_suggest_sheet.dart"
s = open(p, encoding="utf-8").read()

def apply(old, new):
    global s
    if old not in s:
        sys.exit(f"[ai_suggest_sheet.dart] anchor not found, aborting:\n{old[:150]}")
    s = s.replace(old, new, 1)

apply(
'''  bool _busy = false;
  String? _error;
  List<TmdbMovie> _picks = const [];
  int _token = 0;

  /// One-tap moods''',
'''  bool _busy = false;
  String? _error;
  List<TmdbMovie> _picks = const [];
  int _token = 0;

  /// v77: in-memory cache of the last taste query + picks, so closing
  /// this sheet (a dismissible bottom sheet - Flutter tears its whole
  /// State down on close) and reopening it shows what the AI already
  /// generated instead of a blank sheet. Overwritten the moment a new
  /// query is submitted.
  static String? _lastQuery;
  static List<TmdbMovie> _lastPicks = const [];

  @override
  void initState() {
    super.initState();
    if (_lastQuery != null) {
      _tasteCtrl.text = _lastQuery!;
      _picks = _lastPicks;
    }
  }

  /// One-tap moods''')

apply(
'''            'AI is not reachable right now - check the internet and try again.';
      } else {
        _picks = picks;
      }''',
'''            'AI is not reachable right now - check the internet and try again.';
      } else {
        _picks = picks;
        _lastQuery = q;
        _lastPicks = picks;
      }''')

open(p, "w", encoding="utf-8").write(s)
print("  OK")
PYEOF
echo "==> Writing new app icon + splash logo assets"
mkdir -p "android/app/src/main/res/mipmap-mdpi"
