echo "     - the adaptive launcher icon (all 5 densities regenerated,"
echo "       transparent background, properly centered in the safe zone -"
echo "       Android auto-rounds this per-launcher, same as any real app)"
echo "     - the legacy/round icon fallback (older launchers)"
echo "     - the splash screen shown while the app is cold-starting, now"
echo "       inside a rounded white card (was blank white before)"
echo "  2. Movie 'Ask with AI' answers now cached per movie in memory -"
echo "     closing and reopening the sheet keeps the last answer"
echo "  3. 'AI Suggestor' (taste-based movie picks) now restores the last"
echo "     query + results when reopened, instead of starting blank"
echo "  4. Fixed 'new video lags for a second': audio-filter rebuild,"
echo "     subtitle-file scan, and history write no longer block playback"
echo "     from starting - they now run in the background right after"
echo "===================================================================="
echo ""
echo "On low-end-device jitter during playback (not just at video start):"
echo "  I checked hardware-decode wiring and found nothing explicitly"
echo "  configured either way in the Flutter code - which most likely"
echo "  means media_kit is already using its own hardware-accel default"
echo "  under the hood, but I can't confirm that without it running on an"
echo "  actual low-end device. I did NOT add a blind hwdec override here -"
echo "  guessing at that risks making a working setup worse. If it still"
echo "  jitters after this update, tell me: what phone/chipset, and does"
echo "  it happen on ALL videos or just high-resolution/HEVC ones? That'll"
echo "  tell us whether it's a decoder problem or something else."
echo "===================================================================="
